begin;
alter table stores add constraint stores_tenant_unique unique (organization_id,id);
alter table channel_connections add constraint channels_tenant_unique unique (organization_id,store_id,id);
alter table channel_connections add constraint channels_store_tenant foreign key (organization_id,store_id) references stores(organization_id,id);
alter table contacts add column store_id uuid references stores(id), add column external_contact_id text, add column updated_at timestamptz not null default now();
alter table contacts add constraint contacts_store_tenant foreign key (organization_id,store_id) references stores(organization_id,id);
alter table contacts add constraint contacts_scope_unique unique (organization_id,store_id,id);
create unique index contacts_external_unique on contacts(organization_id,store_id,external_contact_id);
alter table conversations add column updated_at timestamptz not null default now();
alter table conversations add constraint conversations_channel_tenant foreign key (organization_id,store_id,channel_connection_id) references channel_connections(organization_id,store_id,id);
alter table conversations add constraint conversations_contact_tenant foreign key (organization_id,store_id,contact_id) references contacts(organization_id,store_id,id);
alter table conversations add constraint conversations_tenant_unique unique (organization_id,id);
create unique index conversations_contact_channel_unique on conversations(organization_id,store_id,channel_connection_id,contact_id);
alter table messages add column message_type text not null default 'text', add column sent_at timestamptz, add column updated_at timestamptz not null default now();
alter table messages add constraint messages_conversation_tenant foreign key (organization_id,conversation_id) references conversations(organization_id,id);
create index messages_conversation_time on messages(organization_id,conversation_id,created_at,id);
alter table webhook_inbox add column status text not null default 'pending' check (status in ('pending','processing','processed','failed')), add column next_attempt_at timestamptz not null default now(), add column updated_at timestamptz not null default now(), add column processing_notes jsonb not null default '[]';
update webhook_inbox set status='processed' where processed_at is not null;
alter table webhook_inbox add constraint inbox_store_tenant foreign key (organization_id,store_id) references stores(organization_id,id);
create index inbox_claim on webhook_inbox(next_attempt_at,received_at) where status in ('pending','failed');
-- Backend uses a dedicated trusted role; no browser policies are granted.
alter table organizations enable row level security;
alter table stores enable row level security;
alter table organization_members enable row level security;
alter table channel_connections enable row level security;
alter table contacts enable row level security;
alter table conversations enable row level security;
alter table messages enable row level security;
commit;
